-- ============================================================
-- Actualización de historias de los lugares - Salta de Mates
-- Basado en investigación de fuentes históricas verificadas
-- ============================================================

USE `salta_de_mates`;

UPDATE `lugares` SET `historia` =
'El Cerro San Bernardo es el cerro tutelar de la ciudad de Salta, parte de la Cordillera Oriental. En 1901 se instaló una cruz en su cima, convirtiéndolo en punto de peregrinación. En 1903 se emplazó una figura de Cristo Redentor. Su acceso tradicional es por la escalinata de piedra con más de 1.000 escalones y 14 templetes del Vía Crucis. El teleférico fue inaugurado el 12 de diciembre de 1987 y recorre 1.000 metros en unos 8 minutos desde el Parque San Martín hasta la cumbre a 1.450 m s.n.m. Cada Viernes Santo miles de fieles suben a pie en peregrinación. Desde la cima se obtiene una vista panorámica incomparable de todo el Valle de Lerma.'
WHERE `nombre` = 'Cerro San Bernardo';

UPDATE `lugares` SET `historia` =
'La Plaza 9 de Julio es el corazón histórico de Salta, fundada el 16 de abril de 1582 por el licenciado Hernando de Lerma como Plaza Mayor. En su centro se clavó el rollo de justicia que simbolizó la fundación de la ciudad. Adoptó su nombre actual en 1884. La rodean las recovas coloniales, la Catedral Basílica (construida entre 1859 y 1882) donde descansan los restos de Güemes, y el Cabildo declarado el mejor conservado de Argentina, que hoy alberga el Museo Histórico del Norte. También se encuentra el MAAM donde se custodian los Niños del Llullaillaco.'
WHERE `nombre` = 'Plaza 9 de Julio';

UPDATE `lugares` SET `historia` =
'El Parque Bicentenario fue construido sobre los predios del ex aeródromo de la ciudad como parte de las obras para conmemorar el Bicentenario de la Revolución de Mayo. Inaugurado en 2015, se convirtió en el pulmón verde más grande de la zona norte de Salta. Cuenta con una laguna artificial, senderos peatonales, anfiteatro al aire libre, canchas deportivas y amplias zonas verdes de césped. Es el parque urbano más moderno de la capital salteña y un punto de encuentro familiar durante los fines de semana.'
WHERE `nombre` = 'Parque Bicentenario';

UPDATE `lugares` SET `historia` =
'La Quebrada de San Lorenzo se ubica a 12 km de la capital salteña, en plena selva de Yungas (del quechua yunka: "valle cálido"). Desde fines del siglo XIX fue el refugio de veraneo favorito de las familias aristocráticas de Salta, quienes construyeron casonas coloniales e inglesas en sus laderas. Un hito histórico de la zona es el Castillo San Lorenzo, edificado por Luigi Bartoletti, armero italiano, con una torre de 25 metros. La reserva natural alberga nogales criollos, helechos gigantes, bromelias, tucanes y el cristalino río San Lorenzo que baja de las cumbres. Ha sido fuente de inspiración para músicos y poetas folclóricos salteños.'
WHERE `nombre` = 'Quebrada de San Lorenzo';

UPDATE `lugares` SET `historia` =
'La Plaza Güemes rinde homenaje al General Martín Miguel de Güemes (1785-1821), héroe de la independencia argentina que organizó la célebre Guerra Gaucha. Con sus milicias gauchas conocidas como "Los Infernales", frenó las invasiones realistas desde el Alto Perú mediante tácticas de desgaste y guerrilla, protegiendo así toda la región del Río de la Plata. El gran Monumento a Güemes, inaugurado el 20 de febrero de 1931 y diseñado por Víctor Juan Garino, se alza 25 metros al pie del Cerro San Bernardo. Sus restos descansan en la Catedral de Salta. Cada 17 de junio, fecha de su muerte, se celebra la tradicional Guardia bajo las Estrellas.'
WHERE `nombre` = 'Plaza Güemes';

UPDATE `lugares` SET `historia` =
'El Paseo de los Poetas es un espacio cultural recuperado por el municipio de Salta a orillas del canal central de la ciudad. Fue concebido como homenaje al rico acervo poético y folclórico salteño. A lo largo de su recorrido exhibe esculturas, murales y placas dedicadas a grandes poetas y compositores de la provincia como Manuel Castilla, Jaime Dávalos y el Cuchi Leguizamón. Con su puente peatonal y su arboleda, se convirtió en un paseo bohemio que conecta el casco histórico con el centro cívico de la ciudad.'
WHERE `nombre` = 'Paseo de los Poetas';

UPDATE `lugares` SET `historia` =
'El Centro Cultural Palacio Zorrilla es una antigua casona del siglo XIX ubicada en el corazón del casco histórico de Salta. Su arquitectura colonial, con patio interior de naranjos y galería de arcos, es característica de las familias patricias salteñas de la época. Fue cedida a la Universidad Nacional de Salta (UNSa) y convertida en sede de actividades culturales, exposiciones, presentaciones de libros y conciertos. Su patio interior, con vegetación perenne y sombra fresca, es uno de los rincones más tranquilos del centro histórico para tomar un mate.'
WHERE `nombre` = 'Centro Cultural Palacio Zorrilla';

UPDATE `lugares` SET `historia` =
'El Mirador del Portezuelo es el histórico acceso oriental a la ciudad de Salta por la Ruta Nacional 9. Ubicado en el filo de los cerros que rodean el Valle de Lerma, fue desde la época colonial el punto desde donde los viajeros divisaban por primera vez la ciudad. Durante décadas fue lugar obligado de bienvenida para turistas que llegaban por tierra desde Buenos Aires. Ofrece una vista panorámica privilegiada de todo el valle y los cerros pintados de verde durante el verano. La ruta que serpentea desde el Portezuelo hacia la capital es conocida localmente como "la bajada del Portezuelo".'
WHERE `nombre` = 'Mirador del Portezuelo';

UPDATE `lugares` SET `historia` =
'La Plaza Alvarado es el corazón verde del tradicional barrio Alvarado, uno de los barrios históricos del macrocentro salteño. Su nombre rinde homenaje al prócer patriota de la independencia sudamericana. Rodeada de frondosos árboles de gran porte que proveen sombra permanente, es punto de encuentro de los vecinos del barrio desde hace décadas. Los fines de semana se instalan puestos de churros, bizcochitos salteños y bebidas calientes que convocan a familias enteras. Es una de las plazas barriales más queridas de la ciudad por su ambiente tranquilo y familiar.'
WHERE `nombre` = 'Plaza Alvarado';

UPDATE `lugares` SET `historia` =
'El Parque Sur fue construido sobre los predios del antiguo Aeropuerto Horacio Guzmán de Salta, cuya actividad fue trasladada al aeropuerto actual. La reconversión del espacio en parque urbano fue una apuesta del gobierno provincial para dotar al sector sur de la ciudad de un pulmón verde y un espacio de recreación. Cuenta con anfiteatro para espectáculos al aire libre, pistas de salud, canchas polideportivas y amplias explanadas de pasto. Es el parque de referencia del sur salteño y sede de festivales culturales, ferias y eventos deportivos durante el año.'
WHERE `nombre` = 'Parque Sur';
